import { useState } from "react";
import { Platform, Pressable, StyleSheet, Text, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { Font } from "@/constants/typography";

// Petite bulle d'aide « ⓘ » : survol (web) ou tap (mobile) -> popover explicatif.
export function InfoHint({ text, align = "right" }: { text: string; align?: "left" | "right" }) {
  const [open, setOpen] = useState(false);
  const hover = Platform.OS === "web" ? { onHoverIn: () => setOpen(true), onHoverOut: () => setOpen(false) } : {};
  return (
    <View style={styles.wrap}>
      <Pressable {...hover} onPress={() => setOpen((v) => !v)} hitSlop={10} style={styles.btn}>
        <Ionicons name="information-circle-outline" size={17} color="#9CA3AF" />
      </Pressable>
      {open ? (
        <View style={[styles.bubble, align === "right" ? { right: 0 } : { left: 0 }]} pointerEvents="none">
          <Text style={styles.bubbleTxt}>{text}</Text>
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { position: "relative" },
  btn: { padding: 5, margin: -5 },
  bubble: {
    position: "absolute",
    top: 22,
    width: 230,
    backgroundColor: "#1B2436",
    borderRadius: 10,
    paddingVertical: 9,
    paddingHorizontal: 12,
    zIndex: 100,
    shadowColor: "#000000",
    shadowOpacity: 0.25,
    shadowRadius: 12,
    shadowOffset: { width: 0, height: 4 },
    elevation: 8,
  },
  bubbleTxt: { color: "#FFFFFF", fontSize: 12, lineHeight: 17, fontFamily: Font.semiBold, includeFontPadding: false },
});
