import { useCallback, useEffect, useState } from "react";
import { StyleSheet, Text, View } from "react-native";
import JovialAdminShell from "@/components/ui/JovialAdminShell";
import PeriodFilter, { DEFAULT_PERIOD, Period } from "@/components/ui/PeriodFilter";
import { ChartCard, KPIStat, LineChart, HBarChart, formatInt, formatEuros, formatCompact } from "@/components/ui/charts";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import {
  getAdminKpis,
  getUsersTimeseries,
  getEstablishmentsTimeseries,
  getSignupFunnel,
  type AdminKpis,
  type TimePoint,
  type SignupFunnel,
} from "@/services/admin";

const pct = (curr: number, prev: number) => (prev > 0 ? (curr - prev) / prev : null);

export default function AdminOverview() {
  const [period, setPeriod] = useState<Period>(DEFAULT_PERIOD);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [kpis, setKpis] = useState<AdminKpis | null>(null);
  const [usersTs, setUsersTs] = useState<TimePoint[]>([]);
  const [estTs, setEstTs] = useState<TimePoint[]>([]);
  const [funnel, setFunnel] = useState<SignupFunnel | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setErr(null);
    try {
      const range = { from: period.from, to: period.to };
      const [k, u, e, f] = await Promise.all([
        getAdminKpis(range),
        getUsersTimeseries(range, period.granularity),
        getEstablishmentsTimeseries(range, period.granularity),
        getSignupFunnel(range),
      ]);
      setKpis(k);
      setUsersTs(u);
      setEstTs(e);
      setFunnel(f);
    } catch (e: any) {
      setErr(e?.message ?? "Erreur de chargement");
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <JovialAdminShell title="Vue d'ensemble" subtitle={period.label} loading={loading} onRefresh={load}>
      <PeriodFilter value={period} onChange={setPeriod} />
      {err ? <Text style={styles.err}>{err}</Text> : null}

      <View style={styles.kpiGrid}>
        <KPIStat label="Utilisateurs" value={formatInt(kpis?.users_total ?? 0)} delta={kpis ? pct(kpis.users_new, kpis.users_new_prev) : null} accent={Pastel.primary} />
        <KPIStat label="Établissements" value={formatInt(kpis?.establishments_total ?? 0)} delta={kpis ? pct(kpis.establishments_new, kpis.establishments_new_prev) : null} accent={Pastel.teal} />
        <KPIStat label="Abonnements actifs" value={formatInt(kpis?.active_subscriptions ?? 0)} accent="#8B5CF6" />
        <KPIStat label="MRR" value={formatEuros(kpis?.mrr_cents ?? 0)} accent="#10B981" />
        <KPIStat label="Réservations (période)" value={formatInt(kpis?.reservations_period ?? 0)} delta={kpis ? pct(kpis.reservations_period, kpis.reservations_prev) : null} accent={Pastel.orange} />
      </View>

      <View style={styles.row}>
        <ChartCard title="Croissance des utilisateurs" subtitle="Cumul" flex={1}>
          <LineChart data={usersTs.map((p) => ({ label: p.bucket, value: p.cumulative ?? p.value }))} area color={Pastel.primary} />
        </ChartCard>
        <ChartCard title="Croissance des établissements" subtitle="Cumul" flex={1}>
          <LineChart data={estTs.map((p) => ({ label: p.bucket, value: p.cumulative ?? p.value }))} area color={Pastel.teal} />
        </ChartCard>
      </View>

      <View style={styles.row}>
        <ChartCard title="Nouveaux utilisateurs" subtitle="Par période" flex={1}>
          <LineChart data={usersTs.map((p) => ({ label: p.bucket, value: p.value }))} color={Pastel.primary} yFormat={formatCompact} />
        </ChartCard>
      </View>

      <View style={styles.row}>
        <ChartCard title="Parcours de conversion — Utilisateurs" flex={1}>
          <HBarChart data={(funnel?.users ?? []).map((s) => ({ label: s.label, value: s.value }))} />
        </ChartCard>
        <ChartCard title="Parcours de conversion — Établissements" flex={1}>
          <HBarChart data={(funnel?.establishments ?? []).map((s) => ({ label: s.label, value: s.value, color: Pastel.teal }))} />
        </ChartCard>
      </View>
    </JovialAdminShell>
  );
}

const styles = StyleSheet.create({
  kpiGrid: { flexDirection: "row", flexWrap: "wrap", gap: 14 },
  row: { flexDirection: "row", flexWrap: "wrap", gap: 18 },
  err: { color: "#DC2626", fontSize: 13, fontFamily: Font.semiBold },
});
