import { Image } from "expo-image";
import { StyleSheet, Text, View } from "react-native";
import { Font } from "@/constants/typography";

// Avatar utilisateur unifié : photo (avatar_url) sinon initiales sur fond coloré
// déterministe. À réutiliser partout (membres de club, posts, commentaires…).
const COLORS = ["#6366F1", "#EC4899", "#F59E0B", "#10B981", "#3B82F6", "#8B5CF6", "#14B8A6", "#F97316"];

function colorFor(seed: string) {
  let n = 0;
  for (let i = 0; i < seed.length; i++) n += seed.charCodeAt(i);
  return COLORS[n % COLORS.length];
}

export function UserAvatar({
  uri,
  name,
  seed,
  size = 44,
}: {
  uri?: string | null;
  name?: string | null;
  seed?: string;
  size?: number;
}) {
  const initials = (name ?? "?").replace("@", "").trim().slice(0, 2).toUpperCase() || "?";
  if (uri) {
    return (
      <Image
        source={{ uri }}
        style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: "#EEF2F7" }}
        contentFit="cover"
        transition={120}
      />
    );
  }
  return (
    <View style={[styles.fallback, { width: size, height: size, borderRadius: size / 2, backgroundColor: colorFor(seed ?? name ?? "?") }]}>
      <Text style={[styles.txt, { fontSize: Math.round(size * 0.36) }]}>{initials}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  fallback: { alignItems: "center", justifyContent: "center" },
  txt: { color: "#FFFFFF", fontFamily: Font.extraBold, includeFontPadding: false },
});
