import React from "react";

import { Pastel } from "@/constants/pastel";

export type DateTimeFieldsProps = {
  dateText: string;
  timeText: string;
  onChangeDate: (v: string) => void;
  onChangeTime: (v: string) => void;
};

// JJ/MM/AAAA -> AAAA-MM-JJ (valeur attendue par <input type="date">)
function frToIso(fr: string): string {
  const m = fr.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : "";
}
// AAAA-MM-JJ -> JJ/MM/AAAA (format attendu par parseEventDateTimeInputs)
function isoToFr(iso: string): string {
  const m = iso.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? `${m[3]}/${m[2]}/${m[1]}` : "";
}

const inputStyle: React.CSSProperties = {
  border: `1px solid ${Pastel.border}`,
  borderRadius: 12,
  padding: "11px 14px",
  fontSize: 15,
  color: Pastel.text,
  background: Pastel.surface,
  fontFamily: "inherit",
  outline: "none",
};

// Variante web : vrais sélecteurs natifs <input type="date"> et <input type="time">.
export function DateTimeFields({ dateText, timeText, onChangeDate, onChangeTime }: DateTimeFieldsProps) {
  return (
    <div style={{ display: "flex", gap: 10 }}>
      <input
        type="date"
        value={frToIso(dateText)}
        onChange={(e) => onChangeDate(isoToFr(e.target.value))}
        style={{ ...inputStyle, flex: 2 }}
      />
      <input
        type="time"
        value={timeText}
        onChange={(e) => onChangeTime(e.target.value)}
        style={{ ...inputStyle, flex: 1 }}
      />
    </div>
  );
}
