import { useCallback, useEffect, useMemo, useState } from "react";
import { Platform, Pressable, StyleSheet, Text, View } from "react-native";
import JovialAdminShell from "@/components/ui/JovialAdminShell";
import PeriodFilter, { DEFAULT_PERIOD, Period } from "@/components/ui/PeriodFilter";
import { ChartCard, KPIStat, LineChart, HBarChart, Donut, formatInt, PALETTE } from "@/components/ui/charts";
import { DataTable, type Column } from "@/components/ui/DataTable";
import { ExportCsvButton } from "@/components/ui/ExportCsvButton";
import { FilterSelect, type FilterOption } from "@/components/ui/FilterSelect";
import { csvDate, type CsvColumn } from "@/utils/csv";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import {
  getUsersTimeseries,
  getUsersByAge,
  getUsersByGender,
  getUsersByRegion,
  getSignupFunnel,
  getAdminKpis,
  listUsers,
  type TimePoint,
  type LabelCount,
  type SignupFunnel,
  type AdminKpis,
  type AdminUserRow,
} from "@/services/admin";

const GENDER_FR: Record<string, string> = {
  female: "Femmes", male: "Hommes", nonbinary: "Non-binaire", other: "Autre", prefer_not: "Non précisé", unknown: "Non renseigné",
};
const AGE_ORDER = ["<18", "18-24", "25-34", "35-44", "45-54", "55-64", "65+"];
const PERIOD_OPTIONS: FilterOption[] = [
  { label: "30 derniers jours", value: "30" },
  { label: "3 derniers mois", value: "90" },
  { label: "6 derniers mois", value: "180" },
  { label: "12 derniers mois", value: "365" },
];
const CONSENT_OPTIONS: FilterOption[] = [
  { label: "A consenti", value: "yes" },
  { label: "Pas de consentement", value: "no" },
];
const USER_LOAD_CAP = 2000;

const frDate = (s: string) => (s ? new Date(s).toLocaleDateString("fr-FR", { day: "2-digit", month: "short", year: "numeric" }) : "—");

const USER_CSV_COLUMNS: CsvColumn<AdminUserRow>[] = [
  { label: "Pseudo", value: (r) => r.handle },
  { label: "Prénom", value: (r) => r.firstname },
  { label: "Email", value: (r) => r.email },
  { label: "Premium", value: (r) => r.is_premium },
  { label: "Consentement email", value: (r) => r.marketing_consent },
  { label: "Ville", value: (r) => r.city },
  { label: "Code postal", value: (r) => r.postcode },
  { label: "Département", value: (r) => r.department },
  { label: "Région", value: (r) => r.geo_zone },
  { label: "Genre", value: (r) => (r.gender ? GENDER_FR[r.gender] ?? r.gender : "") },
  { label: "Tranche d'âge", value: (r) => r.age_bracket },
  { label: "Inscrit le", value: (r) => csvDate(r.created_at) },
];

const distinctOptions = (vals: (string | null)[]): FilterOption[] =>
  Array.from(new Set(vals.filter(Boolean) as string[]))
    .sort((a, b) => a.localeCompare(b, "fr"))
    .map((v) => ({ label: v, value: v }));

export default function AdminUsers() {
  const [period, setPeriod] = useState<Period>(DEFAULT_PERIOD);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [ts, setTs] = useState<TimePoint[]>([]);
  const [age, setAge] = useState<LabelCount[]>([]);
  const [gender, setGender] = useState<LabelCount[]>([]);
  const [zone, setZone] = useState<LabelCount[]>([]);
  const [funnel, setFunnel] = useState<SignupFunnel | null>(null);
  const [kpis, setKpis] = useState<AdminKpis | null>(null);
  const [rows, setRows] = useState<AdminUserRow[]>([]);

  // Filtres d'extraction (table + export CSV)
  const [fPremium, setFPremium] = useState<"" | "yes" | "no">("");
  const [fRegion, setFRegion] = useState("");
  const [fDept, setFDept] = useState("");
  const [fAge, setFAge] = useState("");
  const [fGender, setFGender] = useState("");
  const [fPeriod, setFPeriod] = useState("");
  const [fConsent, setFConsent] = useState<"" | "yes" | "no">("");

  const load = useCallback(async () => {
    setLoading(true);
    setErr(null);
    try {
      const range = { from: period.from, to: period.to };
      const [t, a, g, z, f, k, list] = await Promise.all([
        getUsersTimeseries(range, period.granularity),
        getUsersByAge(),
        getUsersByGender(),
        getUsersByRegion(),
        getSignupFunnel(range),
        getAdminKpis(range),
        listUsers(null, USER_LOAD_CAP, 0),
      ]);
      setTs(t); setAge(a); setGender(g); setZone(z); setFunnel(f); setKpis(k); setRows(list);
    } catch (e: any) {
      setErr(e?.message ?? "Erreur de chargement");
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => { load(); }, [load]);

  const regionOptions = useMemo(() => distinctOptions(rows.map((r) => r.geo_zone)), [rows]);
  const deptOptions = useMemo(() => distinctOptions(rows.map((r) => r.department)), [rows]);
  const ageOptions = useMemo(() => {
    const set = new Set(rows.map((r) => r.age_bracket).filter(Boolean) as string[]);
    return AGE_ORDER.filter((a) => set.has(a)).map((a) => ({ label: a, value: a }));
  }, [rows]);
  const genderOptions = useMemo(() => {
    const set = new Set(rows.map((r) => r.gender).filter(Boolean) as string[]);
    return Array.from(set).sort().map((v) => ({ label: GENDER_FR[v] ?? v, value: v }));
  }, [rows]);

  const filtered = useMemo(() => {
    const cutoff = fPeriod ? Date.now() - Number(fPeriod) * 86400000 : null;
    return rows.filter((r) => {
      if (fPremium === "yes" && !r.is_premium) return false;
      if (fPremium === "no" && r.is_premium) return false;
      if (fRegion && r.geo_zone !== fRegion) return false;
      if (fDept && r.department !== fDept) return false;
      if (fAge && r.age_bracket !== fAge) return false;
      if (fGender && r.gender !== fGender) return false;
      if (fConsent === "yes" && !r.marketing_consent) return false;
      if (fConsent === "no" && r.marketing_consent) return false;
      if (cutoff && (!r.created_at || new Date(r.created_at).getTime() < cutoff)) return false;
      return true;
    });
  }, [rows, fPremium, fRegion, fDept, fAge, fGender, fPeriod, fConsent]);

  const anyFilter = !!(fPremium || fRegion || fDept || fAge || fGender || fPeriod || fConsent);
  const resetFilters = () => { setFPremium(""); setFRegion(""); setFDept(""); setFAge(""); setFGender(""); setFPeriod(""); setFConsent(""); };
  const premiumCount = useMemo(() => rows.filter((r) => r.is_premium).length, [rows]);

  const columns: Column<AdminUserRow>[] = [
    { key: "handle", label: "Pseudo", width: 140, sortValue: (r) => (r.handle ?? "").toLowerCase() },
    { key: "firstname", label: "Prénom", width: 120 },
    { key: "email", label: "Email", width: 230, sortValue: (r) => (r.email ?? "").toLowerCase(), render: (r) => <Text style={styles.cell} numberOfLines={1}>{r.email ?? "—"}</Text> },
    { key: "is_premium", label: "Premium", width: 90, sortValue: (r) => (r.is_premium ? 1 : 0), render: (r) => (r.is_premium ? <Text style={styles.premiumBadge}>⭐ Oui</Text> : <Text style={styles.cellMuted}>—</Text>) },
    { key: "marketing_consent", label: "Consent.", width: 90, sortValue: (r) => (r.marketing_consent ? 1 : 0), render: (r) => (r.marketing_consent ? <Text style={styles.consentBadge}>✓ Oui</Text> : <Text style={styles.cellMuted}>—</Text>) },
    { key: "city", label: "Ville", width: 110, sortValue: (r) => (r.city ?? "").toLowerCase() },
    { key: "department", label: "Département", width: 140, render: (r) => <Text style={styles.cell}>{r.department ?? "—"}</Text> },
    { key: "geo_zone", label: "Région", width: 130, render: (r) => <Text style={styles.cell}>{r.geo_zone ?? "—"}</Text> },
    { key: "age_bracket", label: "Âge", width: 80 },
    { key: "gender", label: "Genre", width: 100, render: (r) => <Text style={styles.cell}>{r.gender ? (GENDER_FR[r.gender] ?? r.gender) : "—"}</Text> },
    { key: "created_at", label: "Inscrit le", width: 120, sortValue: (r) => r.created_at, render: (r) => <Text style={styles.cell}>{frDate(r.created_at)}</Text> },
  ];

  const tableSubtitle = `${filtered.length} affiché${filtered.length > 1 ? "s" : ""}` +
    (anyFilter ? ` (filtré sur ${rows.length})` : "") +
    (rows.length >= USER_LOAD_CAP ? ` — ⚠️ ${USER_LOAD_CAP} max chargés` : "");

  return (
    <JovialAdminShell title="Utilisateurs" subtitle={period.label} loading={loading} onRefresh={load}>
      <PeriodFilter value={period} onChange={setPeriod} />
      {err ? <Text style={styles.err}>{err}</Text> : null}

      <View style={styles.kpiGrid}>
        <KPIStat label="Total utilisateurs" value={formatInt(kpis?.users_total ?? 0)} accent={Pastel.primary} />
        <KPIStat label="Nouveaux (période)" value={formatInt(kpis?.users_new ?? 0)} accent={Pastel.teal} />
        <KPIStat label="Abonnés Jovial+" value={formatInt(premiumCount)} accent={Pastel.orange} sub="Premium actifs (chargés)" />
      </View>

      <ChartCard title="Croissance des utilisateurs" subtitle="Nouveaux par période">
        <LineChart data={ts.map((p) => ({ label: p.bucket, value: p.value }))} area color={Pastel.primary} />
      </ChartCard>

      <View style={styles.row}>
        <ChartCard title="Tranches d'âge" flex={1}>
          <HBarChart data={age.map((d) => ({ label: d.label, value: d.count, color: Pastel.primary }))} />
        </ChartCard>
        <ChartCard title="Genre" flex={1}>
          <Donut data={gender.map((d, i) => ({ label: GENDER_FR[d.label] ?? d.label, value: d.count, color: PALETTE[i % PALETTE.length] }))} centerLabel="users" centerValue={formatInt(gender.reduce((s, d) => s + d.count, 0))} />
        </ChartCard>
      </View>

      <View style={styles.row}>
        <ChartCard title="Par région" flex={1}>
          <HBarChart data={zone.slice(0, 12).map((d) => ({ label: d.label, value: d.count, color: Pastel.teal }))} />
        </ChartCard>
        <ChartCard title="Parcours de conversion" flex={1}>
          <HBarChart data={(funnel?.users ?? []).map((s) => ({ label: s.label, value: s.value }))} />
        </ChartCard>
      </View>

      <ChartCard title="Annuaire & extraction de contacts" subtitle={tableSubtitle}>
        {/* Barre de filtres */}
        <View style={styles.filterBar}>
          <View style={styles.premiumChips}>
            {([["", "Tous"], ["yes", "⭐ Premium"], ["no", "Non-premium"]] as const).map(([v, lbl]) => (
              <Pressable key={v || "all"} style={[styles.chip, fPremium === v && styles.chipOn]} onPress={() => setFPremium(v)}>
                <Text style={[styles.chipTxt, fPremium === v && styles.chipTxtOn]}>{lbl}</Text>
              </Pressable>
            ))}
          </View>
          <FilterSelect label="Région" value={fRegion} options={regionOptions} onChange={setFRegion} allLabel="Toutes" />
          <FilterSelect label="Département" value={fDept} options={deptOptions} onChange={setFDept} allLabel="Tous" />
          <FilterSelect label="Âge" value={fAge} options={ageOptions} onChange={setFAge} allLabel="Tous" />
          <FilterSelect label="Genre" value={fGender} options={genderOptions} onChange={setFGender} allLabel="Tous" />
          <FilterSelect label="Inscription" value={fPeriod} options={PERIOD_OPTIONS} onChange={setFPeriod} allLabel="Toutes dates" />
          <FilterSelect label="Consentement" value={fConsent} options={CONSENT_OPTIONS} onChange={(v) => setFConsent(v as "" | "yes" | "no")} allLabel="Tous" />
          {anyFilter ? (
            <Pressable onPress={resetFilters} style={styles.reset}>
              <Text style={styles.resetTxt}>Réinitialiser</Text>
            </Pressable>
          ) : null}
        </View>

        <ExportCsvButton rows={filtered} columns={USER_CSV_COLUMNS} filenameBase="contacts-utilisateurs" />
        <DataTable
          columns={columns}
          rows={filtered}
          pageSize={15}
          searchKeys={[(r) => r.handle ?? "", (r) => r.firstname ?? "", (r) => r.email ?? "", (r) => r.city ?? "", (r) => r.postcode ?? "", (r) => r.department ?? ""]}
          searchPlaceholder="Rechercher (pseudo, prénom, email, ville)…"
        />
      </ChartCard>
    </JovialAdminShell>
  );
}

const styles = StyleSheet.create({
  kpiGrid: { flexDirection: "row", flexWrap: "wrap", gap: 14 },
  row: { flexDirection: "row", flexWrap: "wrap", gap: 18 },
  err: { color: "#DC2626", fontSize: 13, fontFamily: Font.semiBold },
  cell: { color: "#242D41", fontSize: 13, fontFamily: Font.semiBold, includeFontPadding: false },
  cellMuted: { color: "#9CA3AF", fontSize: 13, fontFamily: Font.semiBold, includeFontPadding: false, textAlign: "center" },
  premiumBadge: { color: "#C2660C", fontSize: 12.5, fontFamily: Font.bold, includeFontPadding: false, textAlign: "center" },
  consentBadge: { color: "#059669", fontSize: 12.5, fontFamily: Font.bold, includeFontPadding: false, textAlign: "center" },

  filterBar: { flexDirection: "row", flexWrap: "wrap", alignItems: "center", gap: 8, marginBottom: 12 },
  premiumChips: { flexDirection: "row", gap: 6 },
  chip: { paddingHorizontal: 12, paddingVertical: 8, borderRadius: 10, borderWidth: 1, borderColor: Pastel.border, backgroundColor: "#FFFFFF", ...(Platform.OS === "web" ? ({ cursor: "pointer" } as object) : {}) },
  chipOn: { backgroundColor: Pastel.primary, borderColor: Pastel.primary },
  chipTxt: { fontSize: 12.5, color: "#6B7280", fontFamily: Font.bold, includeFontPadding: false },
  chipTxtOn: { color: "#FFFFFF" },
  reset: { paddingHorizontal: 10, paddingVertical: 8, ...(Platform.OS === "web" ? ({ cursor: "pointer" } as object) : {}) },
  resetTxt: { fontSize: 12.5, color: Pastel.danger, fontFamily: Font.bold, includeFontPadding: false },
});
