import { ActivityIndicator, StyleSheet, Text, View } from "react-native";
import { Redirect, Stack } from "expo-router";
import { useAuth } from "@/providers/AuthProvider";
import { useIsPlatformAdmin } from "@/hooks/useIsPlatformAdmin";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

// Espace admin plateforme (back-office propriétaire). Accès réservé : un compte non
// présent dans platform_admins est immédiatement renvoyé vers l'entrée de l'app.
export default function AdminLayout() {
  const { session, loading: authLoading } = useAuth();
  const { isAdmin, loading } = useIsPlatformAdmin();

  if (authLoading || loading) {
    return (
      <View style={styles.center}>
        <ActivityIndicator color={Pastel.navyDeep} size="large" />
        <Text style={styles.txt}>Vérification de l'accès…</Text>
      </View>
    );
  }

  // Pas de session OU pas admin -> on renvoie vers l'entrée (AuthGate réoriente proprement).
  if (!session || !isAdmin) {
    return <Redirect href={"/" as any} />;
  }

  return <Stack screenOptions={{ headerShown: false }} />;
}

const styles = StyleSheet.create({
  center: { flex: 1, justifyContent: "center", alignItems: "center", backgroundColor: "#f8faff", gap: 12 },
  txt: { color: "#9CA3AF", fontSize: 13, fontFamily: Font.semiBold, includeFontPadding: false },
});
