import { useEffect, useState } from "react";
import {
  View,
  Text,
  TextInput,
  Pressable,
  StyleSheet,
  Alert,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
} from "react-native";
import { useRouter, useLocalSearchParams } from "expo-router";
import { Ionicons } from "@expo/vector-icons";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { StatusBar } from "expo-status-bar";
import { supabase } from "@/services/supabase";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

// Réinitialisation par CODE à 6 chiffres (pas de deep-link, fiable iOS = Android).
// L'utilisateur arrive ici depuis l'écran de connexion (qui a déjà envoyé l'email avec
// le code via resetPasswordForEmail). On vérifie le code (verifyOtp recovery) puis on
// met à jour le mot de passe (updateUser).
export default function ResetPasswordScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const params = useLocalSearchParams();
  const email = ((params.email as string | undefined) ?? "").trim().toLowerCase();

  const [step, setStep] = useState<"code" | "password">("code");
  const [code, setCode] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [resending, setResending] = useState(false);

  // Arrivée sans email (ancien deep-link, accès direct) -> retour au login.
  useEffect(() => {
    if (!email) {
      Alert.alert("Réinitialisation", "Recommence depuis l'écran de connexion, en saisissant ton email.", [
        { text: "OK", onPress: () => router.replace("/(auth)/login") },
      ]);
    }
  }, [email]);

  const onVerifyCode = async () => {
    const token = code.trim();
    if (token.length < 6) {
      Alert.alert("Code incomplet", "Saisis le code à 6 chiffres reçu par email.");
      return;
    }
    try {
      setLoading(true);
      const { error } = await supabase.auth.verifyOtp({ email, token, type: "recovery" });
      if (error) {
        Alert.alert("Code invalide", "Ce code est incorrect ou expiré. Renvoie-toi un nouveau code.");
        return;
      }
      setStep("password");
    } finally {
      setLoading(false);
    }
  };

  const onResend = async () => {
    try {
      setResending(true);
      const { error } = await supabase.auth.resetPasswordForEmail(email);
      if (error) { Alert.alert("Erreur", error.message); return; }
      Alert.alert("Code renvoyé", "Un nouveau code vient de t'être envoyé par email.");
    } finally {
      setResending(false);
    }
  };

  const onSubmit = async () => {
    if (password.length < 12) {
      Alert.alert("Mot de passe trop court", "Le mot de passe doit faire au moins 12 caractères.");
      return;
    }
    if (password !== confirm) {
      Alert.alert("Mots de passe différents", "Les deux mots de passe ne correspondent pas.");
      return;
    }
    try {
      setLoading(true);
      const { error } = await supabase.auth.updateUser({ password });
      if (error) {
        Alert.alert("Erreur", "Impossible de mettre à jour le mot de passe. " + error.message);
        return;
      }
      Alert.alert("Mot de passe mis à jour", "Tu peux maintenant te connecter avec ton nouveau mot de passe.", [
        { text: "Se connecter", onPress: () => router.replace("/(tabs)/map") },
      ]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <StatusBar style="light" hidden={false} />
      <KeyboardAvoidingView style={styles.root} behavior={Platform.OS === "ios" ? "padding" : "height"}>
        <ScrollView
          style={styles.root}
          contentContainerStyle={[styles.container, { paddingTop: insets.top + 20, paddingBottom: insets.bottom + 32 }]}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          <Pressable style={styles.back} onPress={() => router.replace("/(auth)/login")} hitSlop={10}>
            <Ionicons name="arrow-back" size={20} color="rgba(255,255,255,0.7)" />
          </Pressable>

          {step === "code" ? (
            <>
              <View style={styles.headlineBlock}>
                <Text style={styles.eyebrow}>MOT DE PASSE OUBLIÉ</Text>
                <Text style={styles.headline}>Entre le code</Text>
                <Text style={styles.subline}>
                  On t'a envoyé un code à 6 chiffres à{"\n"}
                  <Text style={styles.emailHL}>{email}</Text>. Saisis-le ci-dessous.
                </Text>
              </View>

              <View style={styles.field}>
                <Text style={styles.label}>Code de vérification</Text>
                <TextInput
                  style={styles.codeInput}
                  placeholder="------"
                  placeholderTextColor="rgba(255,255,255,0.25)"
                  keyboardType="number-pad"
                  maxLength={6}
                  value={code}
                  onChangeText={(t) => setCode(t.replace(/[^0-9]/g, ""))}
                  autoFocus
                  textContentType="oneTimeCode"
                />
                <View style={styles.inputLine} />
              </View>

              <Pressable
                style={({ pressed }) => [styles.btn, loading && styles.btnDisabled, pressed && { opacity: 0.88 }]}
                onPress={onVerifyCode}
                disabled={loading}
              >
                <Text style={styles.btnText}>{loading ? "Vérification..." : "Valider le code"}</Text>
              </Pressable>

              <Pressable style={styles.resend} onPress={onResend} disabled={resending} hitSlop={8}>
                <Text style={styles.resendText}>{resending ? "Envoi..." : "Renvoyer le code"}</Text>
              </Pressable>
            </>
          ) : (
            <>
              <View style={styles.headlineBlock}>
                <Text style={styles.eyebrow}>NOUVEAU MOT DE PASSE</Text>
                <Text style={styles.headline}>Réinitialisation</Text>
                <Text style={styles.subline}>Choisis un nouveau mot de passe d'au moins 12 caractères.</Text>
              </View>

              <View style={styles.form}>
                <View style={styles.field}>
                  <Text style={styles.label}>Nouveau mot de passe</Text>
                  <View style={styles.passwordRow}>
                    <TextInput
                      style={[styles.input, { flex: 1 }]}
                      placeholder="••••••••••••"
                      placeholderTextColor="rgba(255,255,255,0.25)"
                      secureTextEntry={!showPassword}
                      value={password}
                      onChangeText={setPassword}
                      autoComplete="new-password"
                    />
                    <Pressable onPress={() => setShowPassword((v) => !v)} hitSlop={10}>
                      <Ionicons
                        name={showPassword ? "eye-off-outline" : "eye-outline"}
                        size={18}
                        color="rgba(255,255,255,0.4)"
                      />
                    </Pressable>
                  </View>
                  <View style={styles.inputLine} />
                </View>

                <View style={styles.field}>
                  <Text style={styles.label}>Confirmer le mot de passe</Text>
                  <TextInput
                    style={styles.input}
                    placeholder="••••••••••••"
                    placeholderTextColor="rgba(255,255,255,0.25)"
                    secureTextEntry={!showPassword}
                    value={confirm}
                    onChangeText={setConfirm}
                    autoComplete="new-password"
                  />
                  <View style={styles.inputLine} />
                </View>
              </View>

              <Pressable
                style={({ pressed }) => [styles.btn, loading && styles.btnDisabled, pressed && { opacity: 0.88 }]}
                onPress={onSubmit}
                disabled={loading}
              >
                <Text style={styles.btnText}>{loading ? "Mise à jour..." : "Mettre à jour"}</Text>
              </Pressable>
            </>
          )}
        </ScrollView>
      </KeyboardAvoidingView>
    </>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: Pastel.primary },
  container: {
    flexGrow: 1,
    paddingHorizontal: 28,
    gap: 32,
  },
  back: { alignSelf: "flex-start", padding: 4 },
  headlineBlock: { gap: 8 },
  eyebrow: {
    color: Pastel.cream,
    fontSize: 11,
    fontFamily: Font.extraBold,
    letterSpacing: 2.5,
    includeFontPadding: false,
  },
  headline: {
    color: "#FFFFFF",
    fontSize: 44,
    fontFamily: Font.display,
    letterSpacing: 1,
    lineHeight: 50,
    includeFontPadding: false,
  },
  subline: {
    color: "rgba(255,255,255,0.55)",
    fontSize: 14,
    lineHeight: 20,
    fontFamily: Font.regular,
    includeFontPadding: false,
  },
  emailHL: { color: Pastel.cream, fontFamily: Font.semiBold },
  form: { gap: 28 },
  field: { gap: 8 },
  label: {
    color: "rgba(255,255,255,0.5)",
    fontSize: 11,
    fontFamily: Font.extraBold,
    letterSpacing: 1.5,
    textTransform: "uppercase",
    includeFontPadding: false,
  },
  input: {
    color: "#FFFFFF",
    fontSize: 17,
    paddingVertical: 8,
    fontFamily: Font.semiBold,
    includeFontPadding: false,
  },
  codeInput: {
    color: "#FFFFFF",
    fontSize: 30,
    letterSpacing: 10,
    paddingVertical: 8,
    fontFamily: Font.extraBold,
    textAlign: "center",
    includeFontPadding: false,
  },
  passwordRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 10,
  },
  inputLine: {
    height: 1,
    backgroundColor: "rgba(255,255,255,0.18)",
  },
  btn: {
    backgroundColor: Pastel.teal,
    paddingVertical: 17,
    alignItems: "center",
    borderRadius: 14,
    shadowColor: Pastel.teal,
    shadowOpacity: 0.45,
    shadowRadius: 18,
    shadowOffset: { width: 0, height: 6 },
    elevation: 8,
  },
  btnDisabled: { opacity: 0.5 },
  btnText: {
    color: "#FFFFFF",
    fontFamily: Font.extraBold,
    fontSize: 16,
    includeFontPadding: false,
  },
  resend: { alignSelf: "center", paddingVertical: 8 },
  resendText: {
    color: Pastel.cream,
    fontSize: 14,
    fontFamily: Font.semiBold,
    includeFontPadding: false,
  },
});
