import { useCallback, useEffect, useMemo, useState } from "react";
import { StyleSheet, Text, View } from "react-native";

import JovialAdminShell from "@/components/ui/JovialAdminShell";
import { ChartCard, KPIStat, LineChart, formatInt, formatEuros, formatCompact } from "@/components/ui/charts";
import { AlertCard, type AlertTone } from "@/components/ui/AlertCard";
import { CohortMatrix } from "@/components/ui/CohortMatrix";
import { ExportCsvButton } from "@/components/ui/ExportCsvButton";
import { csvDate, type CsvColumn } from "@/utils/csv";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import {
  getActiveUsers,
  getActiveUsersTimeseries,
  getHealthSummary,
  getRetentionCohort,
  getRiskEstablishments,
  getAdminKpis,
  type ActiveUsers,
  type HealthSummary,
  type CohortRow,
  type RiskEstablishment,
  type TimePoint,
  type AdminKpis,
} from "@/services/admin";

const pct = (curr: number, prev: number) => (prev > 0 ? (curr - prev) / prev : null);

const RISK_CSV_COLUMNS: CsvColumn<RiskEstablishment>[] = [
  { label: "Établissement", value: (r) => r.venue_name },
  { label: "Ville", value: (r) => r.city },
  { label: "Plan", value: (r) => r.plan },
  { label: "Abonnement", value: (r) => r.status },
  { label: "Fin d'abonnement", value: (r) => csvDate(r.current_period_end_at) },
  { label: "Jours avant expiration", value: (r) => r.days_to_expiry },
  { label: "Dernière réservation", value: (r) => csvDate(r.last_reservation_at) },
  { label: "Jours sans réservation", value: (r) => r.days_since_reservation },
];

const COHORT_CSV_COLUMNS: CsvColumn<CohortRow>[] = [
  { label: "Cohorte (mois)", value: (r) => r.cohort_month },
  { label: "Taille", value: (r) => r.cohort_size },
  { label: "J+7 (%)", value: (r) => r.d7 },
  { label: "J+30 (%)", value: (r) => r.d30 },
  { label: "J+60 (%)", value: (r) => r.d60 },
  { label: "J+90 (%)", value: (r) => r.d90 },
];

export default function AdminHealth() {
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [active, setActive] = useState<ActiveUsers | null>(null);
  const [activeTs, setActiveTs] = useState<TimePoint[]>([]);
  const [health, setHealth] = useState<HealthSummary | null>(null);
  const [cohort, setCohort] = useState<CohortRow[]>([]);
  const [risk, setRisk] = useState<RiskEstablishment[]>([]);
  const [kpis, setKpis] = useState<AdminKpis | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setErr(null);
    try {
      const today = new Date();
      const from = new Date(today);
      from.setDate(today.getDate() - 30);
      const range = { from: from.toISOString().slice(0, 10), to: today.toISOString().slice(0, 10) };
      const [a, ts, h, c, r, k] = await Promise.all([
        getActiveUsers(),
        getActiveUsersTimeseries(30),
        getHealthSummary(),
        getRetentionCohort(6),
        getRiskEstablishments(),
        getAdminKpis(range),
      ]);
      setActive(a);
      setActiveTs(ts);
      setHealth(h);
      setCohort(c);
      setRisk(r);
      setKpis(k);
    } catch (e: any) {
      setErr(e?.message ?? "Erreur de chargement");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const alerts = useMemo(() => {
    const list: { tone: AlertTone; title: string; detail?: string }[] = [];
    if (health) {
      if (health.at_risk_expiring > 0)
        list.push({ tone: "warning", title: `${health.at_risk_expiring} abonnement${health.at_risk_expiring > 1 ? "s" : ""} expire${health.at_risk_expiring > 1 ? "nt" : ""} sous 30 jours`, detail: "Relance pour éviter le churn." });
      if (health.at_risk_no_reservation > 0)
        list.push({ tone: "warning", title: `${health.at_risk_no_reservation} établissement${health.at_risk_no_reservation > 1 ? "s" : ""} sans réservation depuis 30 jours`, detail: "Signal de désengagement." });
      if (health.churn_rate >= 5)
        list.push({ tone: "danger", title: `Churn établissement élevé : ${health.churn_rate}%`, detail: `${health.churned_30d} résiliation${health.churned_30d > 1 ? "s" : ""} sur 30 jours.` });
      if (health.no_show_rate >= 15)
        list.push({ tone: "danger", title: `Taux de no-show élevé : ${health.no_show_rate}%`, detail: "Qualité de service à surveiller." });
      if (list.length === 0)
        list.push({ tone: "ok", title: "Aucune alerte — tout est au vert", detail: "Churn, no-show et abonnements sous contrôle." });
    }
    return list;
  }, [health]);

  const riskFlag = (r: RiskEstablishment) => {
    if (r.days_to_expiry !== null && r.days_to_expiry <= 30)
      return `Expire dans ${Math.max(0, r.days_to_expiry)} j`;
    if (r.days_since_reservation !== null) return `${r.days_since_reservation} j sans réservation`;
    return "Aucune réservation";
  };

  return (
    <JovialAdminShell title="Santé" subtitle="Pouls de la marketplace — état actuel" loading={loading} onRefresh={load}>
      {err ? <Text style={styles.err}>{err}</Text> : null}

      {/* Usage & croissance */}
      <View style={styles.kpiGrid}>
        <KPIStat label="Actifs / mois (MAU)" value={formatInt(active?.mau ?? 0)} delta={active ? pct(active.mau, active.mau_prev) : null} accent={Pastel.primary} sub="Au moins 1 action sur 30 j" />
        <KPIStat label="Actifs / jour (DAU)" value={formatInt(active?.dau ?? 0)} accent={Pastel.teal} sub="Actifs aujourd'hui" />
        <KPIStat label="Stickiness" value={`${active?.stickiness ?? 0}%`} accent="#8B5CF6" sub="DAU / MAU" />
        <KPIStat label="MRR" value={formatEuros(kpis?.mrr_cents ?? 0)} accent="#10B981" sub="Revenu mensuel récurrent" />
      </View>

      {/* Santé business */}
      <View style={styles.kpiGrid}>
        <KPIStat label="Churn établissement" value={`${health?.churn_rate ?? 0}%`} accent={(health?.churn_rate ?? 0) >= 5 ? Pastel.danger : Pastel.textMuted} sub="Résiliations / 30 j" />
        <KPIStat label="Établissements à risque" value={formatInt((health?.at_risk_expiring ?? 0) + (health?.at_risk_no_reservation ?? 0))} accent={Pastel.orange} sub="Expiration <30j ou inactifs" />
        <KPIStat label="No-show" value={`${health?.no_show_rate ?? 0}%`} accent={(health?.no_show_rate ?? 0) >= 15 ? Pastel.danger : Pastel.textMuted} sub="Réservations non honorées / 30 j" />
        <KPIStat label="Réservations / 30 j" value={formatInt(health?.reservations_30d ?? 0)} accent={Pastel.primary} />
      </View>

      {/* Alertes */}
      {alerts.length > 0 ? (
        <View style={styles.alerts}>
          {alerts.map((a, i) => (
            <AlertCard key={i} tone={a.tone} title={a.title} detail={a.detail} />
          ))}
        </View>
      ) : null}

      {/* Graphe actifs / jour */}
      <View style={styles.row}>
        <ChartCard title="Utilisateurs actifs / jour" subtitle="30 derniers jours (proxy : utilisateurs ayant fait une action)" flex={1}>
          <LineChart data={activeTs.map((p) => ({ label: p.bucket, value: p.value }))} area color={Pastel.teal} yFormat={formatCompact} />
        </ChartCard>
      </View>

      {/* Rétention par cohorte */}
      <View style={styles.row}>
        <ChartCard title="Rétention par cohorte" subtitle="% d'inscrits encore actifs N jours après leur arrivée" flex={1}>
          <ExportCsvButton rows={cohort} columns={COHORT_CSV_COLUMNS} filenameBase="retention-cohortes" />
          <CohortMatrix rows={cohort} />
        </ChartCard>
      </View>

      {/* Établissements à risque */}
      <View style={styles.row}>
        <ChartCard title="Établissements à risque" subtitle="Abonnement expirant <30j ou aucune réservation depuis 30j" flex={1}>
          <ExportCsvButton rows={risk} columns={RISK_CSV_COLUMNS} filenameBase="etablissements-a-risque" />
          {risk.length === 0 ? (
            <Text style={styles.empty}>Aucun établissement à risque 🎉</Text>
          ) : (
            <View style={styles.riskList}>
              {risk.map((r) => (
                <View key={r.venue_id} style={styles.riskRow}>
                  <View style={{ flex: 1 }}>
                    <Text style={styles.riskName} numberOfLines={1}>{r.venue_name ?? "—"}</Text>
                    <Text style={styles.riskMeta} numberOfLines={1}>
                      {[r.city, r.plan].filter(Boolean).join(" · ")}
                    </Text>
                  </View>
                  <Text style={styles.riskFlag}>{riskFlag(r)}</Text>
                </View>
              ))}
            </View>
          )}
        </ChartCard>
      </View>
    </JovialAdminShell>
  );
}

const styles = StyleSheet.create({
  kpiGrid: { flexDirection: "row", flexWrap: "wrap", gap: 14, marginBottom: 4 },
  row: { flexDirection: "row", flexWrap: "wrap", gap: 18 },
  alerts: { gap: 10, marginVertical: 4 },
  err: { color: "#DC2626", fontSize: 13, fontFamily: Font.semiBold },
  empty: { fontSize: 13, color: Pastel.textMuted, padding: 16, textAlign: "center", includeFontPadding: false },
  riskList: { gap: 0 },
  riskRow: { flexDirection: "row", alignItems: "center", gap: 12, paddingVertical: 11, borderBottomWidth: 1, borderBottomColor: Pastel.border },
  riskName: { fontSize: 14, fontFamily: Font.bold, color: Pastel.text, includeFontPadding: false },
  riskMeta: { fontSize: 12.5, color: Pastel.textMuted, marginTop: 2, includeFontPadding: false },
  riskFlag: { fontSize: 12.5, fontFamily: Font.bold, color: "#92400E", includeFontPadding: false },
});
