import { Pressable, StyleSheet, Text, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";

import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

export type AlertTone = "danger" | "warning" | "ok";

const TONE: Record<AlertTone, { bg: string; border: string; fg: string; icon: keyof typeof Ionicons.glyphMap }> = {
  danger: { bg: "#FEF2F2", border: "#FECACA", fg: "#B91C1C", icon: "alert-circle" },
  warning: { bg: "#FFFBEB", border: "#FDE68A", fg: "#92400E", icon: "warning" },
  ok: { bg: "#ECFDF5", border: "#A7F3D0", fg: "#065F46", icon: "checkmark-circle" },
};

export function AlertCard({
  tone,
  title,
  detail,
  onPress,
}: {
  tone: AlertTone;
  title: string;
  detail?: string;
  onPress?: () => void;
}) {
  const t = TONE[tone];
  const Wrap: any = onPress ? Pressable : View;
  return (
    <Wrap style={[styles.card, { backgroundColor: t.bg, borderColor: t.border }]} onPress={onPress}>
      <Ionicons name={t.icon} size={18} color={t.fg} />
      <View style={{ flex: 1 }}>
        <Text style={[styles.title, { color: t.fg }]}>{title}</Text>
        {detail ? <Text style={styles.detail}>{detail}</Text> : null}
      </View>
      {onPress ? <Ionicons name="chevron-forward" size={16} color={t.fg} /> : null}
    </Wrap>
  );
}

const styles = StyleSheet.create({
  card: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    borderWidth: 1,
    borderRadius: 14,
    paddingHorizontal: 16,
    paddingVertical: 13,
  },
  title: { fontSize: 14, fontFamily: Font.bold, includeFontPadding: false },
  detail: { fontSize: 12.5, color: Pastel.textMuted, marginTop: 2, includeFontPadding: false },
});
