import { ReactNode } from "react";
import { ActivityIndicator, Image, Pressable, ScrollView, StyleSheet, Text, useWindowDimensions, View } from "react-native";
import { usePathname, useRouter } from "expo-router";
import { Ionicons } from "@expo/vector-icons";
import { supabase } from "@/services/supabase";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

type NavItem = { key: string; label: string; icon: keyof typeof Ionicons.glyphMap; route: string };

const NAV: NavItem[] = [
  { key: "overview", label: "Vue d'ensemble", icon: "grid-outline", route: "/admin" },
  { key: "health", label: "Santé", icon: "heart-outline", route: "/admin/health" },
  { key: "establishments", label: "Établissements", icon: "business-outline", route: "/admin/establishments" },
  { key: "users", label: "Utilisateurs", icon: "people-outline", route: "/admin/users" },
  { key: "revenue", label: "Revenus", icon: "cash-outline", route: "/admin/revenue" },
  { key: "engagement", label: "Engagement", icon: "pulse-outline", route: "/admin/engagement" },
  { key: "geography", label: "Géographie", icon: "map-outline", route: "/admin/geography" },
  { key: "leaderboards", label: "Classements", icon: "trophy-outline", route: "/admin/leaderboards" },
  { key: "feedback", label: "Retours étab.", icon: "bulb-outline", route: "/admin/feedback" },
];

const DESKTOP_MIN = 1040;

export default function JovialAdminShell({
  title,
  subtitle,
  right,
  loading,
  onRefresh,
  children,
}: {
  title: string;
  subtitle?: string;
  right?: ReactNode;
  loading?: boolean;
  onRefresh?: () => void;
  children: ReactNode;
}) {
  const { width } = useWindowDimensions();
  const desktop = width >= DESKTOP_MIN;
  const router = useRouter();
  const pathname = usePathname();

  const isActive = (route: string) => (route === "/admin" ? pathname === "/admin" : pathname.startsWith(route));

  const logout = async () => {
    await supabase.auth.signOut();
    router.replace("/" as any);
  };

  const Nav = (
    <View style={[styles.nav, desktop ? styles.navDesktop : styles.navMobile]}>
      <View style={[styles.brandRow, !desktop && { marginBottom: 0 }]}>
        <Image source={require("../../assets/images/logo_mascotte.png")} style={styles.brandLogo} resizeMode="contain" />
        <View style={{ flex: 1 }}>
          <Text style={styles.brandName}>Jovial Admin</Text>
          <Text style={styles.brandSub}>Back-office</Text>
        </View>
      </View>

      <ScrollView
        horizontal={!desktop}
        showsHorizontalScrollIndicator={false}
        showsVerticalScrollIndicator={false}
        contentContainerStyle={desktop ? styles.navListDesktop : styles.navListMobile}
      >
        {NAV.map((item) => {
          const on = isActive(item.route);
          return (
            <Pressable key={item.key} onPress={() => router.replace(item.route as any)} style={[styles.navItem, !desktop && styles.navItemMobile, on && styles.navItemOn]}>
              <Ionicons name={item.icon} size={18} color={on ? "#FFFFFF" : "rgba(255,255,255,0.65)"} />
              <Text style={[styles.navTxt, on && styles.navTxtOn]} numberOfLines={1}>{item.label}</Text>
            </Pressable>
          );
        })}
      </ScrollView>

      {desktop ? (
        <View style={styles.bottomLinks}>
          <Pressable onPress={() => router.push("/establishment/dashboard" as any)} style={styles.logoutBtn}>
            <Ionicons name="storefront-outline" size={18} color="rgba(255,255,255,0.7)" />
            <Text style={styles.logoutTxt}>Mon espace Jovial Pro</Text>
          </Pressable>
          <Pressable onPress={logout} style={styles.logoutBtn}>
            <Ionicons name="log-out-outline" size={18} color="rgba(255,255,255,0.7)" />
            <Text style={styles.logoutTxt}>Déconnexion</Text>
          </Pressable>
        </View>
      ) : null}
    </View>
  );

  const Main = (
    <View style={styles.mainWrap}>
      <View style={styles.header}>
        <View style={{ flex: 1 }}>
          <Text style={styles.title}>{title}</Text>
          {subtitle ? <Text style={styles.subtitle}>{subtitle}</Text> : null}
        </View>
        {right}
        {onRefresh ? (
          <Pressable onPress={onRefresh} style={styles.refreshBtn} hitSlop={8}>
            {loading ? <ActivityIndicator size="small" color={Pastel.primary} /> : <Ionicons name="refresh" size={18} color={Pastel.primary} />}
          </Pressable>
        ) : null}
      </View>
      <ScrollView style={styles.scroll} contentContainerStyle={styles.scrollContent} showsVerticalScrollIndicator={false}>
        <View style={styles.contentMax}>{children}</View>
      </ScrollView>
    </View>
  );

  if (desktop) {
    return (
      <View style={styles.rootDesktop}>
        {Nav}
        {Main}
      </View>
    );
  }
  return (
    <View style={styles.rootMobile}>
      {Nav}
      {Main}
    </View>
  );
}

const styles = StyleSheet.create({
  rootDesktop: { flex: 1, flexDirection: "row", backgroundColor: "#F4F6FB" },
  rootMobile: { flex: 1, backgroundColor: "#F4F6FB" },

  nav: { backgroundColor: Pastel.navyDeep },
  navDesktop: { width: 244, paddingVertical: 22, paddingHorizontal: 16, justifyContent: "flex-start" },
  navMobile: { paddingTop: 14, paddingBottom: 10, paddingHorizontal: 12, gap: 10 },
  brandRow: { flexDirection: "row", alignItems: "center", gap: 10, marginBottom: 22, paddingHorizontal: 6 },
  brandLogo: { width: 38, height: 38 },
  brandName: { color: "#FFFFFF", fontSize: 17, fontFamily: Font.extraBold, includeFontPadding: false },
  brandSub: { color: "rgba(255,255,255,0.5)", fontSize: 11, fontFamily: Font.semiBold, includeFontPadding: false },

  navListDesktop: { gap: 4 },
  navListMobile: { gap: 8, paddingRight: 12 },
  navItem: { flexDirection: "row", alignItems: "center", gap: 11, paddingVertical: 11, paddingHorizontal: 13, borderRadius: 11 },
  navItemMobile: { paddingVertical: 9 },
  navItemOn: { backgroundColor: "rgba(255,255,255,0.14)" },
  navTxt: { color: "rgba(255,255,255,0.65)", fontSize: 14, fontFamily: Font.bold, includeFontPadding: false },
  navTxtOn: { color: "#FFFFFF" },
  bottomLinks: { marginTop: "auto", gap: 2 },
  logoutBtn: { flexDirection: "row", alignItems: "center", gap: 10, paddingVertical: 11, paddingHorizontal: 13 },
  logoutTxt: { color: "rgba(255,255,255,0.7)", fontSize: 14, fontFamily: Font.bold, includeFontPadding: false },

  mainWrap: { flex: 1 },
  header: { flexDirection: "row", alignItems: "center", gap: 12, paddingHorizontal: 24, paddingVertical: 18, borderBottomWidth: 1, borderBottomColor: "#E9EDF5", backgroundColor: "#FFFFFF" },
  title: { color: "#1B2436", fontSize: 22, fontFamily: Font.extraBold, includeFontPadding: false },
  subtitle: { color: "#9CA3AF", fontSize: 13, fontFamily: Font.regular, marginTop: 2, includeFontPadding: false },
  refreshBtn: { width: 40, height: 40, borderRadius: 12, backgroundColor: "#EEF2FF", alignItems: "center", justifyContent: "center" },
  scroll: { flex: 1 },
  scrollContent: { padding: 20, paddingBottom: 60 },
  contentMax: { width: "100%", maxWidth: 1200, alignSelf: "center", gap: 18 },
});
