import { useState } from "react";
import { Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { usePathname } from "expo-router";
import { Ionicons } from "@expo/vector-icons";

import JovialProShell from "@/components/ui/JovialProShell";
import { useEstablishment } from "@/providers/EstablishmentProvider";
import { useAuth } from "@/providers/AuthProvider";
import { supabase } from "@/services/supabase";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

const CATEGORIES: { key: "idea" | "bug" | "other"; label: string; icon: keyof typeof Ionicons.glyphMap }[] = [
  { key: "idea", label: "Idée / souhait", icon: "bulb-outline" },
  { key: "bug", label: "Bug / problème", icon: "warning-outline" },
  { key: "other", label: "Autre", icon: "chatbubble-ellipses-outline" },
];

export default function EstablishmentFeedbackScreen() {
  const pathname = usePathname();
  const { venue } = useEstablishment();
  const { session } = useAuth();
  const userId = session?.user?.id ?? null;

  const [category, setCategory] = useState<"idea" | "bug" | "other">("idea");
  const [message, setMessage] = useState("");
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);

  const submit = async () => {
    const body = message.trim();
    if (!body || !userId || sending) return;
    setSending(true);
    const { error } = await supabase.from("establishment_feedback").insert({
      venue_id: venue?.id ?? null,
      user_id: userId,
      category,
      message: body,
    });
    setSending(false);
    if (!error) {
      setSent(true);
      setMessage("");
    }
  };

  return (
    <JovialProShell
      title="Idées & retours"
      subtitle="Aide-nous à améliorer Jovial — ton avis compte 💛"
      currentPath={pathname}
    >
      <View style={styles.card}>
        {sent ? (
          <View style={styles.sentBox}>
            <Ionicons name="checkmark-circle" size={40} color={Pastel.teal} />
            <Text style={styles.sentTitle}>Merci, c'est envoyé !</Text>
            <Text style={styles.sentSub}>On lit chaque retour. Tu peux en envoyer un autre quand tu veux.</Text>
            <Pressable style={styles.secondaryBtn} onPress={() => setSent(false)}>
              <Text style={styles.secondaryBtnText}>Envoyer un autre retour</Text>
            </Pressable>
          </View>
        ) : (
          <>
            <Text style={styles.label}>De quoi s'agit-il ?</Text>
            <View style={styles.catRow}>
              {CATEGORIES.map((c) => {
                const active = category === c.key;
                return (
                  <Pressable key={c.key} style={[styles.catChip, active ? styles.catChipActive : null]} onPress={() => setCategory(c.key)}>
                    <Ionicons name={c.icon} size={16} color={active ? "#FFFFFF" : Pastel.text} />
                    <Text style={[styles.catChipText, active ? styles.catChipTextActive : null]}>{c.label}</Text>
                  </Pressable>
                );
              })}
            </View>

            <Text style={[styles.label, { marginTop: 18 }]}>Ton message</Text>
            <TextInput
              value={message}
              onChangeText={setMessage}
              placeholder="Décris ton idée, ton souci ou ta suggestion…"
              placeholderTextColor={Pastel.textMuted}
              style={styles.input}
              multiline
              maxLength={1500}
            />

            <Pressable
              style={[styles.submitBtn, !message.trim() || sending ? styles.submitDisabled : null]}
              onPress={submit}
              disabled={!message.trim() || sending}
            >
              <Ionicons name="paper-plane-outline" size={16} color="#FFFFFF" />
              <Text style={styles.submitText}>{sending ? "Envoi…" : "Envoyer"}</Text>
            </Pressable>
          </>
        )}
      </View>
    </JovialProShell>
  );
}

const styles = StyleSheet.create({
  card: { backgroundColor: Pastel.surface, borderRadius: 24, borderWidth: 1, borderColor: Pastel.border, padding: 24, maxWidth: 720, gap: 4 },
  label: { fontSize: 13, fontFamily: Font.bold, color: Pastel.text, includeFontPadding: false, marginBottom: 10 },
  catRow: { flexDirection: "row", gap: 10, flexWrap: "wrap" },
  catChip: { flexDirection: "row", alignItems: "center", gap: 8, paddingHorizontal: 14, paddingVertical: 10, borderRadius: 999, borderWidth: 1, borderColor: Pastel.border, backgroundColor: Pastel.surfaceAlt },
  catChipActive: { backgroundColor: Pastel.primary, borderColor: Pastel.primary },
  catChipText: { fontSize: 13.5, fontFamily: Font.semiBold, color: Pastel.text, includeFontPadding: false },
  catChipTextActive: { color: "#FFFFFF" },
  input: {
    minHeight: 140,
    borderWidth: 1,
    borderColor: Pastel.border,
    borderRadius: 14,
    backgroundColor: Pastel.surfaceAlt,
    padding: 14,
    fontSize: 15,
    color: Pastel.text,
    fontFamily: Font.regular,
    textAlignVertical: "top",
  },
  submitBtn: { flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 8, marginTop: 18, paddingVertical: 13, borderRadius: 14, backgroundColor: Pastel.primary, alignSelf: "flex-start", paddingHorizontal: 24 },
  submitDisabled: { opacity: 0.4 },
  submitText: { color: "#FFFFFF", fontFamily: Font.bold, fontSize: 15, includeFontPadding: false },
  sentBox: { alignItems: "center", gap: 10, paddingVertical: 24 },
  sentTitle: { fontSize: 18, fontFamily: Font.extraBold, color: Pastel.text, includeFontPadding: false },
  sentSub: { fontSize: 14, color: Pastel.textMuted, textAlign: "center", includeFontPadding: false, maxWidth: 420 },
  secondaryBtn: { marginTop: 8, paddingVertical: 10, paddingHorizontal: 18, borderRadius: 999, borderWidth: 1, borderColor: Pastel.border, backgroundColor: Pastel.surfaceAlt },
  secondaryBtnText: { fontSize: 13.5, fontFamily: Font.bold, color: Pastel.text, includeFontPadding: false },
});
