import { useState } from "react";
import { Platform, Pressable, StyleSheet, Text, ViewStyle } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import { csvFilename, downloadCsv, toCsv, type CsvColumn } from "@/utils/csv";

type Props<T> = {
  rows: T[];
  columns: CsvColumn<T>[];
  filenameBase: string;
  label?: string;
  style?: ViewStyle;
};

// Bouton d'export CSV (back-office = web). Rendu nul sur natif.
export function ExportCsvButton<T>({ rows, columns, filenameBase, label = "Exporter CSV", style }: Props<T>) {
  const [done, setDone] = useState(false);
  if (Platform.OS !== "web") return null;

  const disabled = rows.length === 0;
  const onPress = () => {
    if (disabled) return;
    const ok = downloadCsv(csvFilename(filenameBase), toCsv(rows, columns));
    if (ok) {
      setDone(true);
      setTimeout(() => setDone(false), 2000);
    }
  };

  return (
    <Pressable
      style={[styles.btn, disabled && styles.btnDisabled, style]}
      onPress={onPress}
      disabled={disabled}
      accessibilityRole="button"
    >
      <Ionicons
        name={done ? "checkmark" : "download-outline"}
        size={15}
        color={disabled ? Pastel.textMuted : done ? Pastel.teal : Pastel.primary}
      />
      <Text style={[styles.text, disabled && styles.textDisabled, done && styles.textDone]}>
        {done ? "Exporté ✓" : `${label} (${rows.length})`}
      </Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  btn: {
    flexDirection: "row",
    alignItems: "center",
    gap: 7,
    paddingVertical: 8,
    paddingHorizontal: 14,
    borderRadius: 10,
    borderWidth: 1,
    borderColor: Pastel.primary,
    backgroundColor: "#FFFFFF",
    alignSelf: "flex-start",
    marginBottom: 12,
    ...(Platform.OS === "web" ? ({ cursor: "pointer" } as object) : {}),
  },
  btnDisabled: { borderColor: "#E5E7EB", backgroundColor: "#F9FAFB" },
  text: { color: Pastel.primary, fontSize: 13, fontFamily: Font.bold, includeFontPadding: false },
  textDisabled: { color: Pastel.textMuted },
  textDone: { color: Pastel.teal },
});
