import { StyleSheet, Text, View } from "react-native";

import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import type { CohortRow } from "@/services/admin";

// Heatmap : 0% rouge -> 50% jaune -> 100% vert (teinte HSL 0->120).
function heatColor(pct: number | null): string {
  if (pct === null || pct === undefined) return "transparent";
  const p = Math.max(0, Math.min(100, pct));
  const hue = (p / 100) * 120;
  return `hsl(${Math.round(hue)}, 70%, 86%)`;
}

const COLS = [
  { key: "d7", label: "J+7" },
  { key: "d30", label: "J+30" },
  { key: "d60", label: "J+60" },
  { key: "d90", label: "J+90" },
] as const;

export function CohortMatrix({ rows }: { rows: CohortRow[] }) {
  if (rows.length === 0) {
    return <Text style={styles.empty}>Pas encore assez de données de cohortes.</Text>;
  }
  return (
    <View style={styles.table}>
      <View style={[styles.row, styles.headerRow]}>
        <Text style={[styles.cell, styles.cohortCell, styles.headerText]}>Cohorte</Text>
        <Text style={[styles.cell, styles.sizeCell, styles.headerText]}>Inscrits</Text>
        {COLS.map((c) => (
          <Text key={c.key} style={[styles.cell, styles.dataCell, styles.headerText]}>{c.label}</Text>
        ))}
      </View>
      {rows.map((r) => (
        <View key={r.cohort_month} style={styles.row}>
          <Text style={[styles.cell, styles.cohortCell, styles.cohortText]}>{r.cohort_month}</Text>
          <Text style={[styles.cell, styles.sizeCell, styles.sizeText]}>{r.cohort_size}</Text>
          {COLS.map((c) => {
            const v = r[c.key];
            return (
              <View key={c.key} style={[styles.cell, styles.dataCell, { backgroundColor: heatColor(v) }]}>
                <Text style={styles.dataText}>{v === null || v === undefined ? "—" : `${v}%`}</Text>
              </View>
            );
          })}
        </View>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  table: { borderWidth: 1, borderColor: Pastel.border, borderRadius: 14, overflow: "hidden", backgroundColor: Pastel.surface },
  row: { flexDirection: "row", alignItems: "stretch", minHeight: 40, borderBottomWidth: 1, borderBottomColor: Pastel.border },
  headerRow: { backgroundColor: Pastel.surfaceAlt },
  cell: { justifyContent: "center", alignItems: "center", paddingVertical: 9, paddingHorizontal: 6 },
  cohortCell: { flex: 1.4, alignItems: "flex-start", paddingHorizontal: 14 },
  sizeCell: { flex: 0.9 },
  dataCell: { flex: 1 },
  headerText: { fontSize: 12, fontFamily: Font.extraBold, color: Pastel.textMuted, includeFontPadding: false },
  cohortText: { fontSize: 13, fontFamily: Font.bold, color: Pastel.text, includeFontPadding: false },
  sizeText: { fontSize: 13, fontFamily: Font.semiBold, color: Pastel.text, includeFontPadding: false },
  dataText: { fontSize: 12.5, fontFamily: Font.bold, color: Pastel.text, includeFontPadding: false },
  empty: { fontSize: 13, color: Pastel.textMuted, padding: 16, textAlign: "center", includeFontPadding: false },
});
