import { Redirect, Tabs, useRouter } from "expo-router";
import { getFocusedRouteNameFromRoute } from "@react-navigation/native";
import { Ionicons } from "@expo/vector-icons";

import { useCallback, useEffect, useState } from "react";
import { AppState, Platform, useWindowDimensions } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import * as Notifications from "expo-notifications";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { useAuth } from "@/providers/AuthProvider";
import { isDesktopWeb } from "@/utils/platform";
import { supabase } from "@/services/supabase";
import { emitNotificationsChanged, onNotificationsChanged } from "@/utils/notifEvents";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

const LAST_CHAT_READ_KEY = "last_chat_read_at";

function useUnreadCount(userId: string | null) {
  const [count, setCount] = useState(0);

  useEffect(() => {
    if (!userId) { setCount(0); return; }

    const fetchCount = () => {
      supabase
        .from("notifications")
        .select("id", { count: "exact", head: true })
        .eq("user_id", userId)
        .eq("read", false)
        .then(({ count: c }: { count: number | null }) => setCount(c ?? 0));
    };

    fetchCount();

    // Temps reel Supabase (si active) : nouvelles notifs / changements distants.
    const channel = supabase
      .channel(`notif-badge-${userId}`)
      .on("postgres_changes", { event: "*", schema: "public", table: "notifications", filter: `user_id=eq.${userId}` }, fetchCount)
      .subscribe();

    // Signal interne : marquage "lu" depuis l'ecran Notifications -> on recompte aussitot.
    const off = onNotificationsChanged(fetchCount);

    return () => { supabase.removeChannel(channel); off(); };
  }, [userId]);

  return count;
}

function useUnreadMessages(userId: string | null) {
  const [count, setCount] = useState(0);

  const refresh = useCallback(async () => {
    if (!userId) { setCount(0); return; }
    const lastRead = await AsyncStorage.getItem(LAST_CHAT_READ_KEY).catch(() => null);
    let query = supabase
      .from("chat_messages")
      .select("id", { count: "exact", head: true })
      .eq("recipient_id", userId);
    if (lastRead) query = query.gt("created_at", lastRead);
    const { count: c } = await query;
    setCount(c ?? 0);
  }, [userId]);

  useEffect(() => {
    refresh();
    const channel = supabase
      .channel(`chat-badge-${userId}`)
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "chat_messages", filter: `recipient_id=eq.${userId}` }, refresh)
      .subscribe();
    // Recompte quand un chat est marqué lu (chat.tsx émet l'événement) -> le badge tombe.
    const off = onNotificationsChanged(refresh);
    return () => { supabase.removeChannel(channel); off(); };
  }, [userId, refresh]);

  return { count, refresh };
}

// Demandes d'adhésion en attente, sur les clubs que l'utilisateur administre.
function usePendingJoinRequests(userId: string | null) {
  const [count, setCount] = useState(0);
  useEffect(() => {
    if (!userId) { setCount(0); return; }
    let cancelled = false;
    const fetchCount = async () => {
      const { data: admin } = await supabase
        .from("community_group_members")
        .select("group_id")
        .eq("user_id", userId)
        .in("role", ["admin", "founder"])
        .eq("status", "approved");
      const ids = ((admin as any[]) ?? []).map((r) => r.group_id);
      if (ids.length === 0) { if (!cancelled) setCount(0); return; }
      const { count: c } = await supabase
        .from("community_group_members")
        .select("user_id", { count: "exact", head: true })
        .in("group_id", ids)
        .eq("status", "pending");
      if (!cancelled) setCount(c ?? 0);
    };
    fetchCount();
    const channel = supabase
      .channel(`group-requests-${userId}`)
      .on("postgres_changes", { event: "*", schema: "public", table: "community_group_members" }, fetchCount)
      .subscribe();
    return () => { cancelled = true; supabase.removeChannel(channel); };
  }, [userId]);
  return count;
}

export default function TabsLayout() {
  const router = useRouter();
  const { session, loading } = useAuth();
  const { width } = useWindowDimensions();
  const desktopWeb = isDesktopWeb(width);
  const unreadCount = useUnreadCount(session?.user?.id ?? null);
  const { count: unreadMessages } = useUnreadMessages(session?.user?.id ?? null);
  const pendingRequests = usePendingJoinRequests(session?.user?.id ?? null);
  const insets = useSafeAreaInsets();

  // Badge de l'icône d'app = total non-lu (notifs + messages). On le garde synchronisé :
  // dès que le compteur change, et à chaque retour de l'app au premier plan (réconcilie
  // un badge laissé par un push reçu en arrière-plan). -> le "1" disparaît après lecture.
  const totalBadge = unreadCount + unreadMessages;
  useEffect(() => {
    Notifications.setBadgeCountAsync(totalBadge).catch(() => {});
  }, [totalBadge]);
  useEffect(() => {
    const sub = AppState.addEventListener("change", (state) => {
      // Au retour au 1er plan : on RECOMPTE depuis la base (un push reçu en arrière-plan
      // n'a pas été vu par le temps réel) -> totalBadge se met à jour -> l'effet ci-dessus
      // écrit le bon badge. On ne réécrit PAS un total périmé.
      if (state === "active") emitNotificationsChanged();
    });
    return () => sub.remove();
  }, []);

  // Sur Android avec barre de navigation à l'écran, insets.bottom > 0
  // On ajoute cet espace au paddingBottom pour que les onglets ne soient pas cachés
  const tabBarPaddingBottom = Math.max(insets.bottom, Platform.OS === "android" ? 8 : 4);
  const tabBarHeight = 56 + tabBarPaddingBottom;
  const tabBarStyle = {
    backgroundColor: Pastel.surface,
    borderTopColor: Pastel.border,
    borderTopWidth: 1,
    height: tabBarHeight,
    paddingBottom: tabBarPaddingBottom,
    paddingTop: 6,
  };

  if (desktopWeb) {
    if (loading) return null;
    return <Redirect href={"/establishment/dashboard" as any} />;
  }

  return (
    <Tabs
      screenOptions={{
        headerShown: false,
        tabBarStyle,
        tabBarActiveTintColor: Pastel.primary,
        tabBarInactiveTintColor: Pastel.textMuted,
        tabBarLabelStyle: {
          fontSize: 11,
          fontFamily: Font.semiBold,
        },
      }}
    >
      <Tabs.Screen
        name="map"
        options={{
          title: "Carte",
          tabBarIcon: ({ color, size }) => (
            <Ionicons name="map-outline" size={size} color={color} />
          ),
        }}
      />

      <Tabs.Screen
        name="explore"
        options={{
          title: "Explorer",
          tabBarIcon: ({ color, size }) => (
            <Ionicons name="search-outline" size={size} color={color} />
          ),
        }}
      />

      <Tabs.Screen
        name="events"
        options={{ href: null }}
      />

      <Tabs.Screen
        name="groups"
        options={({ route }) => {
          const focused = getFocusedRouteNameFromRoute(route);
          const hideBar = !!focused && focused.endsWith("compose");
          return {
            title: "Club",
            tabBarIcon: ({ color, size }) => (
              <Ionicons name="people-outline" size={size} color={color} />
            ),
            tabBarStyle: hideBar ? { display: "none" as const } : tabBarStyle,
            tabBarBadge: pendingRequests > 0 ? (pendingRequests > 99 ? "99+" : pendingRequests) : undefined,
            tabBarBadgeStyle: { backgroundColor: "#EF4444", color: "#FFFFFF", fontSize: 10, minWidth: 16, height: 16 },
          };
        }}
      />

      <Tabs.Screen
        name="notifications"
        options={{
          title: "Notifications",
          tabBarIcon: ({ color, size }) => (
            <Ionicons name="notifications-outline" size={size} color={color} />
          ),
          tabBarBadge: unreadCount > 0 ? (unreadCount > 99 ? "99+" : unreadCount) : undefined,
          tabBarBadgeStyle: { backgroundColor: "#EF4444", color: "#FFFFFF", fontSize: 10, minWidth: 16, height: 16 },
        }}
      />

      <Tabs.Screen
        name="profile"
        options={{
          title: "Profil",
          tabBarIcon: ({ color, size }) => (
            <Ionicons name="person-outline" size={size} color={color} />
          ),
        }}
        listeners={({ navigation }) => ({
          tabPress: () => {
            navigation.navigate("profile", { screen: "index" });
          },
        })}
      />

      {/* Onglets template masqués */}
      <Tabs.Screen name="index" options={{ href: null }} />
      <Tabs.Screen name="places" options={{ href: null }} />
    </Tabs>
  );
}
