import { useState } from "react";
import { Modal, Platform, Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";

export type FilterOption = { label: string; value: string };

type Props = {
  label: string;
  value: string; // "" = tous
  options: FilterOption[];
  onChange: (v: string) => void;
  allLabel?: string;
};

// Petit menu déroulant filtrant (back-office). "" = aucun filtre.
export function FilterSelect({ label, value, options, onChange, allLabel = "Tous" }: Props) {
  const [open, setOpen] = useState(false);
  const active = !!value;
  const current = active ? options.find((o) => o.value === value)?.label ?? value : allLabel;

  return (
    <>
      <Pressable style={[styles.btn, active && styles.btnActive]} onPress={() => setOpen(true)}>
        <Text style={styles.btnLabel} numberOfLines={1}>
          {label} : <Text style={[styles.btnValue, active && styles.btnValueActive]}>{current}</Text>
        </Text>
        <Ionicons name="chevron-down" size={13} color={active ? Pastel.primary : Pastel.textMuted} />
      </Pressable>

      <Modal visible={open} transparent animationType="fade" onRequestClose={() => setOpen(false)}>
        <Pressable style={styles.overlay} onPress={() => setOpen(false)}>
          <View style={styles.menu}>
            <Text style={styles.menuTitle}>{label}</Text>
            <ScrollView style={styles.menuScroll} keyboardShouldPersistTaps="handled">
              <Pressable style={styles.opt} onPress={() => { onChange(""); setOpen(false); }}>
                <Text style={[styles.optText, !active && styles.optTextActive]}>{allLabel}</Text>
                {!active ? <Ionicons name="checkmark" size={16} color={Pastel.primary} /> : null}
              </Pressable>
              {options.map((o) => (
                <Pressable key={o.value} style={styles.opt} onPress={() => { onChange(o.value); setOpen(false); }}>
                  <Text style={[styles.optText, value === o.value && styles.optTextActive]} numberOfLines={1}>{o.label}</Text>
                  {value === o.value ? <Ionicons name="checkmark" size={16} color={Pastel.primary} /> : null}
                </Pressable>
              ))}
            </ScrollView>
          </View>
        </Pressable>
      </Modal>
    </>
  );
}

const styles = StyleSheet.create({
  btn: {
    flexDirection: "row",
    alignItems: "center",
    gap: 6,
    paddingVertical: 8,
    paddingHorizontal: 12,
    borderRadius: 10,
    borderWidth: 1,
    borderColor: Pastel.border,
    backgroundColor: "#FFFFFF",
    ...(Platform.OS === "web" ? ({ cursor: "pointer" } as object) : {}),
  },
  btnActive: { borderColor: Pastel.primary, backgroundColor: "#F5F8FF" },
  btnLabel: { fontSize: 12.5, color: Pastel.textMuted, fontFamily: Font.semiBold, includeFontPadding: false },
  btnValue: { color: Pastel.text, fontFamily: Font.bold },
  btnValueActive: { color: Pastel.primary },

  overlay: { flex: 1, backgroundColor: "rgba(0,0,0,0.35)", alignItems: "center", justifyContent: "center", padding: 24 },
  menu: { width: "100%", maxWidth: 380, backgroundColor: "#FFFFFF", borderRadius: 16, paddingVertical: 10, paddingHorizontal: 6, gap: 2 },
  menuTitle: { fontSize: 13, fontFamily: Font.extraBold, color: Pastel.textMuted, paddingHorizontal: 12, paddingVertical: 6, includeFontPadding: false },
  menuScroll: { maxHeight: 380 },
  opt: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", gap: 10, paddingVertical: 11, paddingHorizontal: 12, borderRadius: 9 },
  optText: { fontSize: 14, color: Pastel.text, fontFamily: Font.semiBold, includeFontPadding: false, flex: 1 },
  optTextActive: { color: Pastel.primary, fontFamily: Font.bold },
});
