import { Pressable, StyleSheet, Text, View } from "react-native";
import { Image } from "expo-image";

import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import type { MentionUser } from "@/hooks/useMentionAutocomplete";

export function MentionDropdown({ suggestions, onSelect }: { suggestions: MentionUser[]; onSelect: (u: MentionUser) => void }) {
  if (suggestions.length === 0) return null;
  return (
    <View style={styles.wrap}>
      {suggestions.map((u) => (
        <Pressable key={u.user_id} style={styles.row} onPress={() => onSelect(u)}>
          {u.avatar_url ? (
            <Image source={{ uri: u.avatar_url }} style={styles.avatar} contentFit="cover" transition={100} />
          ) : (
            <View style={[styles.avatar, styles.avatarFallback]}>
              <Text style={styles.avatarInitial}>{(u.firstname ?? u.handle ?? "?").slice(0, 1).toUpperCase()}</Text>
            </View>
          )}
          <Text style={styles.name} numberOfLines={1}>
            {u.firstname ? `${u.firstname} ` : ""}
            {u.handle ? <Text style={styles.handle}>@{u.handle}</Text> : null}
          </Text>
        </Pressable>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: {
    backgroundColor: Pastel.surface,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: Pastel.border,
    overflow: "hidden",
    shadowColor: "#000",
    shadowOpacity: 0.1,
    shadowRadius: 10,
    shadowOffset: { width: 0, height: 4 },
    elevation: 4,
  },
  row: { flexDirection: "row", alignItems: "center", gap: 10, paddingHorizontal: 12, paddingVertical: 8 },
  avatar: { width: 28, height: 28, borderRadius: 14, backgroundColor: Pastel.surfaceAlt },
  avatarFallback: { alignItems: "center", justifyContent: "center" },
  avatarInitial: { fontSize: 12, fontFamily: Font.bold, color: Pastel.primary, includeFontPadding: false },
  name: { flex: 1, fontSize: 13.5, fontFamily: Font.semiBold, color: Pastel.text, includeFontPadding: false },
  handle: { color: Pastel.textMuted, fontFamily: Font.regular },
});
