import { useCallback, useEffect, useState } from "react";
import { ActivityIndicator, Alert, Modal, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import JovialAdminShell from "@/components/ui/JovialAdminShell";
import PeriodFilter, { DEFAULT_PERIOD, Period } from "@/components/ui/PeriodFilter";
import { ChartCard, KPIStat, LineChart, HBarChart, Donut, formatInt, PALETTE } from "@/components/ui/charts";
import { DataTable, type Column } from "@/components/ui/DataTable";
import { ExportCsvButton } from "@/components/ui/ExportCsvButton";
import { csvDate, type CsvColumn } from "@/utils/csv";
import { Pastel } from "@/constants/pastel";
import { Font } from "@/constants/typography";
import {
  getEstablishmentsTimeseries,
  getEstablishmentsByType,
  getEstablishmentsByCity,
  getAdminKpis,
  listEstablishments,
  setVenueModeration,
  type TimePoint,
  type LabelCount,
  type AdminEstablishmentRow,
  type AdminKpis,
  type ModerationStatus,
} from "@/services/admin";

const MOD_LABEL: Record<ModerationStatus, string> = { active: "Actif", suspended: "Suspendu", removed: "Retiré" };

const frDate = (s: string) => (s ? new Date(s).toLocaleDateString("fr-FR", { day: "2-digit", month: "short", year: "numeric" }) : "—");

const EST_CSV_COLUMNS: CsvColumn<AdminEstablishmentRow>[] = [
  { label: "Établissement", value: (r) => r.name },
  { label: "Ville", value: (r) => r.city },
  { label: "Type", value: (r) => r.venue_type },
  { label: "Plan", value: (r) => r.plan },
  { label: "Abonnement", value: (r) => r.sub_status },
  { label: "État", value: (r) => MOD_LABEL[r.moderation_status] },
  { label: "Actif", value: (r) => r.is_active },
  { label: "Réservations", value: (r) => r.reservations_count },
  { label: "Charte acceptée le", value: (r) => csvDate(r.charter_accepted_at) },
  { label: "Inscrit le", value: (r) => csvDate(r.created_at) },
];

export default function AdminEstablishments() {
  const [period, setPeriod] = useState<Period>(DEFAULT_PERIOD);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  const [ts, setTs] = useState<TimePoint[]>([]);
  const [byType, setByType] = useState<LabelCount[]>([]);
  const [byCity, setByCity] = useState<LabelCount[]>([]);
  const [kpis, setKpis] = useState<AdminKpis | null>(null);
  const [rows, setRows] = useState<AdminEstablishmentRow[]>([]);
  const [modTarget, setModTarget] = useState<AdminEstablishmentRow | null>(null);
  const [modAction, setModAction] = useState<ModerationStatus>("suspended");
  const [modReason, setModReason] = useState("");
  const [modBusy, setModBusy] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setErr(null);
    try {
      const range = { from: period.from, to: period.to };
      const [t, ty, ci, k, list] = await Promise.all([
        getEstablishmentsTimeseries(range, period.granularity),
        getEstablishmentsByType(),
        getEstablishmentsByCity(12),
        getAdminKpis(range),
        listEstablishments(null, 200, 0),
      ]);
      setTs(t); setByType(ty); setByCity(ci); setKpis(k); setRows(list);
    } catch (e: any) {
      setErr(e?.message ?? "Erreur de chargement");
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => { load(); }, [load]);

  const openMod = (r: AdminEstablishmentRow, action: ModerationStatus) => {
    setModTarget(r);
    setModAction(action);
    setModReason("");
  };
  const confirmMod = async () => {
    if (!modTarget) return;
    setModBusy(true);
    try {
      await setVenueModeration(modTarget.venue_id, modAction, modReason);
      setModTarget(null);
      await load();
    } catch (e: any) {
      Alert.alert("Erreur", e?.message ?? "Action impossible");
    } finally {
      setModBusy(false);
    }
  };

  const modBadge = (s: ModerationStatus) => (s === "active" ? styles.badgeActive : s === "suspended" ? styles.badgeSuspended : styles.badgeRemoved);

  const columns: Column<AdminEstablishmentRow>[] = [
    { key: "name", label: "Établissement", width: 180, sortValue: (r) => (r.name ?? "").toLowerCase() },
    { key: "city", label: "Ville", width: 120, sortValue: (r) => (r.city ?? "").toLowerCase() },
    {
      key: "plan", label: "Plan", width: 100,
      render: (r) => <Text style={[styles.badge, r.plan && r.plan !== "visibilite" ? styles.badgePaid : styles.badgeFree]}>{r.plan ?? "—"}</Text>,
    },
    {
      key: "moderation_status", label: "État", width: 95, sortValue: (r) => r.moderation_status,
      render: (r) => <Text style={[styles.badge, modBadge(r.moderation_status)]}>{MOD_LABEL[r.moderation_status]}</Text>,
    },
    {
      key: "charter", label: "Charte", width: 70, align: "right",
      render: (r) => <Text style={r.charter_accepted_at ? styles.ok : styles.cellMuted}>{r.charter_accepted_at ? "✓" : "—"}</Text>,
    },
    { key: "reservations_count", label: "Résa", width: 65, align: "right", sortValue: (r) => r.reservations_count },
    { key: "created_at", label: "Inscrit le", width: 115, sortValue: (r) => r.created_at, render: (r) => <Text style={styles.cell}>{frDate(r.created_at)}</Text> },
    {
      key: "actions", label: "Modération", width: 210,
      render: (r) => (
        <View style={styles.actions}>
          {r.moderation_status !== "active" ? (
            <Pressable style={[styles.actBtn, styles.actActive]} onPress={() => openMod(r, "active")}><Text style={styles.actTxt}>Réactiver</Text></Pressable>
          ) : null}
          {r.moderation_status === "active" ? (
            <Pressable style={[styles.actBtn, styles.actSuspend]} onPress={() => openMod(r, "suspended")}><Text style={styles.actTxt}>Suspendre</Text></Pressable>
          ) : null}
          {r.moderation_status !== "removed" ? (
            <Pressable style={[styles.actBtn, styles.actRemove]} onPress={() => openMod(r, "removed")}><Text style={styles.actTxt}>Retirer</Text></Pressable>
          ) : null}
        </View>
      ),
    },
  ];

  return (
    <JovialAdminShell title="Établissements" subtitle={period.label} loading={loading} onRefresh={load}>
      <PeriodFilter value={period} onChange={setPeriod} />
      {err ? <Text style={styles.err}>{err}</Text> : null}

      <View style={styles.kpiGrid}>
        <KPIStat label="Total" value={formatInt(kpis?.establishments_total ?? 0)} accent={Pastel.teal} />
        <KPIStat label="Nouveaux (période)" value={formatInt(kpis?.establishments_new ?? 0)} accent={Pastel.primary} />
        <KPIStat label="Payants" value={formatInt(kpis?.paying_establishments ?? 0)} accent="#10B981" />
        <KPIStat label="Gratuits" value={formatInt(kpis?.free_establishments ?? 0)} accent="#9CA3AF" />
      </View>

      <View style={styles.row}>
        <ChartCard title="Croissance" subtitle="Cumul des établissements" flex={1}>
          <LineChart data={ts.map((p) => ({ label: p.bucket, value: p.cumulative ?? p.value }))} area color={Pastel.teal} />
        </ChartCard>
        <ChartCard title="Par type" flex={1}>
          <Donut data={byType.map((d, i) => ({ label: d.label, value: d.count, color: PALETTE[i % PALETTE.length] }))} centerLabel="établ." centerValue={formatInt(byType.reduce((s, d) => s + d.count, 0))} />
        </ChartCard>
      </View>

      <ChartCard title="Top villes" subtitle="Nombre d'établissements">
        <HBarChart data={byCity.map((d) => ({ label: d.label, value: d.count, color: Pastel.teal }))} />
      </ChartCard>

      <ChartCard title="Tous les établissements" subtitle={`${rows.length} au total — tu peux suspendre / retirer un établissement ici`}>
        <ExportCsvButton rows={rows} columns={EST_CSV_COLUMNS} filenameBase="etablissements" />
        <DataTable
          columns={columns}
          rows={rows}
          pageSize={15}
          searchKeys={[(r) => r.name ?? "", (r) => r.city ?? "", (r) => r.venue_type ?? "", (r) => r.plan ?? ""]}
          searchPlaceholder="Rechercher un établissement (nom, ville, type, plan)…"
        />
      </ChartCard>

      <Modal visible={!!modTarget} transparent animationType="fade" onRequestClose={() => setModTarget(null)}>
        <View style={styles.modalOverlay}>
          <View style={styles.modalCard}>
            <Text style={styles.modalTitle}>
              {modAction === "active" ? "Réactiver" : modAction === "suspended" ? "Suspendre" : "Retirer"} « {modTarget?.name ?? "cet établissement"} » ?
            </Text>
            {modAction === "active" ? (
              <Text style={styles.modalInfo}>L'établissement réapparaîtra immédiatement dans l'application.</Text>
            ) : (
              <Text style={styles.modalWarn}>⚠️ L'établissement disparaîtra de l'application. Pense à rembourser le prorata de l'abonnement s'il est payant.</Text>
            )}
            <TextInput
              value={modReason}
              onChangeText={setModReason}
              placeholder="Motif (interne, optionnel)"
              placeholderTextColor="#9CA3AF"
              style={styles.modalInput}
              multiline
            />
            <View style={styles.modalRow}>
              <Pressable style={styles.modalCancel} onPress={() => setModTarget(null)}><Text style={styles.modalCancelTxt}>Annuler</Text></Pressable>
              <Pressable style={[styles.modalConfirm, modAction === "removed" && { backgroundColor: "#DC2626" }, modAction === "active" && { backgroundColor: "#10B981" }]} onPress={confirmMod} disabled={modBusy}>
                {modBusy ? <ActivityIndicator color="#FFFFFF" /> : <Text style={styles.modalConfirmTxt}>Confirmer</Text>}
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>
    </JovialAdminShell>
  );
}

const styles = StyleSheet.create({
  kpiGrid: { flexDirection: "row", flexWrap: "wrap", gap: 14 },
  row: { flexDirection: "row", flexWrap: "wrap", gap: 18 },
  err: { color: "#DC2626", fontSize: 13, fontFamily: Font.semiBold },
  cell: { color: "#242D41", fontSize: 13, fontFamily: Font.semiBold, includeFontPadding: false },
  badge: { fontSize: 11, fontFamily: Font.bold, paddingHorizontal: 8, paddingVertical: 3, borderRadius: 7, overflow: "hidden", textTransform: "capitalize" },
  badgePaid: { backgroundColor: "#ECFDF5", color: "#059669" },
  badgeFree: { backgroundColor: "#F3F4F6", color: "#6B7280" },
  badgeActive: { backgroundColor: "#ECFDF5", color: "#059669" },
  badgeSuspended: { backgroundColor: "#FFF7ED", color: "#C2660C" },
  badgeRemoved: { backgroundColor: "#FEF2F2", color: "#DC2626" },
  ok: { color: "#10B981", fontSize: 14, fontFamily: Font.bold },
  cellMuted: { color: "#9CA3AF", fontSize: 13, fontFamily: Font.semiBold },
  actions: { flexDirection: "row", gap: 6, flexWrap: "wrap" },
  actBtn: { paddingHorizontal: 10, paddingVertical: 6, borderRadius: 8 },
  actActive: { backgroundColor: "#10B981" },
  actSuspend: { backgroundColor: "#F59E0B" },
  actRemove: { backgroundColor: "#EF4444" },
  actTxt: { color: "#FFFFFF", fontSize: 12, fontFamily: Font.bold, includeFontPadding: false },

  modalOverlay: { flex: 1, backgroundColor: "rgba(0,0,0,0.45)", alignItems: "center", justifyContent: "center", padding: 24 },
  modalCard: { width: "100%", maxWidth: 440, backgroundColor: "#FFFFFF", borderRadius: 18, padding: 22, gap: 14 },
  modalTitle: { color: "#1B2436", fontSize: 17, fontFamily: Font.extraBold, includeFontPadding: false },
  modalWarn: { color: "#92400E", fontSize: 13, fontFamily: Font.semiBold, backgroundColor: "#FFF7ED", borderRadius: 10, padding: 12, lineHeight: 19 },
  modalInfo: { color: "#065F46", fontSize: 13, fontFamily: Font.semiBold, backgroundColor: "#ECFDF5", borderRadius: 10, padding: 12, lineHeight: 19 },
  modalInput: { backgroundColor: "#F3F4F6", borderRadius: 10, paddingHorizontal: 12, paddingVertical: 10, fontSize: 14, color: "#242D41", minHeight: 60, textAlignVertical: "top" },
  modalRow: { flexDirection: "row", justifyContent: "flex-end", gap: 10 },
  modalCancel: { paddingHorizontal: 18, paddingVertical: 11, borderRadius: 11, backgroundColor: "#F3F4F6" },
  modalCancelTxt: { color: "#6B7280", fontSize: 14, fontFamily: Font.bold, includeFontPadding: false },
  modalConfirm: { paddingHorizontal: 22, paddingVertical: 11, borderRadius: 11, backgroundColor: Pastel.primary, minWidth: 110, alignItems: "center" },
  modalConfirmTxt: { color: "#FFFFFF", fontSize: 14, fontFamily: Font.extraBold, includeFontPadding: false },
});
